mapper.select:
SELECT p.post_id AS postId, p.user_id AS userId, u.nickname AS authorName, u.avatar AS authorAvatar, p.title, p.content, p.images, p.like_count AS likeCount, p.collect_count AS collectCount, p.comment_count AS commentCount, p.view_count AS viewCount, p.status, p.create_time AS createTime, p.update_time AS updateTime, CASE WHEN pl.like_id IS NOT NULL THEN 1 ELSE 0 END AS isLiked, CASE WHEN pc.collect_id IS NOT NULL THEN 1 ELSE 0 END AS isCollected FROM forum_post p LEFT JOIN `user` u ON p.user_id = u.user_id LEFT JOIN forum_post_like pl ON pl.post_id = p.post_id AND pl.user_id = COALESCE(#{viewerUserId}, -1) LEFT JOIN forum_post_collect pc ON pc.post_id = p.post_id AND pc.user_id = COALESCE(#{viewerUserId}, -1)
p.status = 1
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
AND 1 = 0
AND p.user_id IN
#{fid}
ORDER BY ${orderBy}
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE forum_post
SET like_count = CASE WHEN like_count > 0 THEN like_count - 1 ELSE 0 END
WHERE post_id = #{postId}

UPDATE forum_post
SET collect_count = CASE WHEN collect_count > 0 THEN collect_count - 1 ELSE 0 END
WHERE post_id = #{postId}

UPDATE forum_post
SET comment_count = CASE WHEN comment_count > 0 THEN comment_count - 1 ELSE 0 END
WHERE post_id = #{postId}

UPDATE forum_comment
SET like_count = CASE WHEN like_count > 0 THEN like_count - 1 ELSE 0 END
WHERE comment_id = #{commentId}
